import java.io.*;
import java.util.*;

public class Cutting {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine();
        int n = Integer.parseInt(input.split(" ")[0]);
        int bitCoins = Integer.parseInt(input.split(" ")[1]);
        String[] values = br.readLine().split(" ");

        ArrayList<Integer> costs = new ArrayList<Integer>();
        int odd = 0;
        int even = 0;

        for (int i = 0; i < n - 1; i++) {
            if (Integer.parseInt(values[i]) % 2 == 0) {
                even++;
            } else {
                odd++;
            }
            if (odd == even) {
                int diff = Integer.parseInt(values[i + 1]) - Integer.parseInt(values[i]);
                if (diff < 0) {
                    diff = -diff;
                }
                int index = Collections.binarySearch(costs, diff);
                if (index < 0) {
                    index = -index - 1;
                }
                costs.add(index, diff);
            }
        }

        int count = 0;
        for (int cost : costs) {
            if (cost <= bitCoins) {
                bitCoins -= cost;
                count++;
            } else {
                break;
            }
        }
        System.out.println(count);
    }
}
